const safe=v=>String(v||'').slice(0,4000);const masked=v=>v?('*'.repeat(Math.max(0,v.length-4))+v.slice(-4)):'';
export default async function handler(req,res){if(req.method==='GET'){const mode=req.query?.['hub.mode'],token=req.query?.['hub.verify_token'],challenge=req.query?.['hub.challenge'];if(mode==='subscribe'&&token&&token===process.env.WHATSAPP_VERIFY_TOKEN)return res.status(200).send(challenge);return res.status(403).json({error:'Verification failed'});}if(req.method!=='POST')return res.status(405).json({error:'Method not allowed'});try{const value=req.body?.entry?.[0]?.changes?.[0]?.value,msg=value?.messages?.[0];if(!msg)return res.status(200).json({ok:true});const from=safe(msg.from),id=safe(msg.id);console.log(JSON.stringify({event:'whatsapp_message',id,from:masked(from),type:msg.type,receivedAt:new Date().toISOString()}));/* Persist + enqueue orchestration here. Do not log message bodies/full phone numbers. */return res.status(200).json({ok:true});}catch(e){console.error('WhatsApp webhook error');return res.status(200).json({ok:true});}}